from typing import List, Dict, Any
import csv
import io
import re
from collections import Counter

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def split_physical_rows(lines_list):
        rows = []
        buf = []
        in_quote = False
        quote_char = '"'
        for line in lines_list:
            if not buf:
                buf = [line]
            else:
                buf.append(line)
            i = 0
            while i < len(line):
                ch = line[i]
                if ch == quote_char:
                    if in_quote and i + 1 < len(line) and line[i + 1] == quote_char:
                        i += 1
                    else:
                        in_quote = not in_quote
                i += 1
            if not in_quote:
                rows.append("\n".join(buf))
                buf = []
        if buf:
            rows.append("\n".join(buf))
        return rows

    def parse_with_dialect(s: str, delim: str = ",", quote: str = '"'):
        reader = csv.reader(io.StringIO(s), delimiter=delim, quotechar=quote, doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    def normalize_row(row: List[str], width: int):
        if width <= 0:
            return row
        if len(row) == width:
            return row
        if len(row) < width:
            return row + [""] * (width - len(row))
        if width == 1:
            return [",".join(row)]
        head = row[:width - 1]
        tail = ",".join(row[width - 1:])
        return head + [tail]

    physical_rows = split_physical_rows(lines)

    candidate_start = 0
    for i, r in enumerate(physical_rows):
        if r.strip():
            candidate_start = i
            break

    data_rows = physical_rows[candidate_start:]
    parsed = parse_with_dialect("\n".join(data_rows), ",", '"')

    if not parsed:
        return {"columns": [], "rows": []}

    header = parsed[0]
    rows = parsed[1:]

    if len(header) == 1 and "," in header[0]:
        alt = parse_with_dialect("\n".join(data_rows), ",", "'")
        if alt and len(alt[0]) > 1:
            parsed = alt
            header = parsed[0]
            rows = parsed[1:]

    width = max([len(header)] + [len(r) for r in rows] + [10])

    header = normalize_row(header, width)
    norm_rows = [normalize_row(r, width) for r in rows]

    if len(header) == 10 and header[0].strip().upper() == "DATE" and header[1].strip().upper() == "TIME":
        pass

    return {"columns": header, "rows": norm_rows}
